import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";import"./chunks/assets.NJs4UO-Q.js";var i=JSON.parse(`{"title":"在 Codex 中使用","description":"","frontmatter":{},"headers":[],"relativePath":"third-party-tools/codex.md","filePath":"zh/third-party-tools/codex.md"}`),a={name:`third-party-tools/codex.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="在-codex-中使用" tabindex="-1">在 Codex 中使用 <a class="header-anchor" href="#在-codex-中使用" aria-label="Permalink to “在 Codex 中使用”">​</a></h1><p><a href="https://openai.com/zh-Hans-CN/codex/" target="_blank" rel="noreferrer">Codex</a> 是 OpenAI 提供的编程 Agent。本文介绍如何通过 CC Switch，将 Codex CLI 接入 Kimi For Coding，由 Kimi K3 或 Kimi K2.7 Code 提供模型推理能力。</p><div class="warning custom-block"><p class="custom-block-title">社区第三方接入方案，仅供参考</p><p>CC Switch + Codex 为社区提供的第三方接入方案，内容仅供参考。该方案不在官方维护与支持范围内，我们无法保证其与各版本 Codex / CC Switch 的兼容性。如遇 API 兼容性问题，请结合您的实际环境自行排查修复，也欢迎将解决方案分享至社区。</p></div><blockquote><p>Codex CLI 目前支持文本和图片输入，但尚未提供原生视频输入通道，无法将视频文件直接作为多模态输入提交给模型。若需分析视频，可先用 ffmpeg 提取关键帧并配合音频转写后交给模型处理。这是 Codex CLI 输入层的限制，并非 Kimi K3 模型的能力限制——Kimi K3 API 原生支持视频输入。</p></blockquote><h2 id="会员权限" tabindex="-1">会员权限 <a class="header-anchor" href="#会员权限" aria-label="Permalink to “会员权限”">​</a></h2><p>配置前先了解自己的会员档位，再根据下表选择合适的模型和上下文窗口参数：</p><table tabindex="0"><thead><tr><th>会员档位</th><th>可用模型</th><th>上下文窗口</th></tr></thead><tbody><tr><td>Andante</td><td><code>kimi-for-coding</code></td><td>256K</td></tr><tr><td>Moderato</td><td><code>k3</code><br><code>k3-256k</code><br><code>kimi-for-coding</code></td><td>均为 256K</td></tr><tr><td>Allegretto 及以上</td><td><code>k3</code><br><code>k3-256k</code><br><code>kimi-for-coding</code><br><code>kimi-for-coding-highspeed</code></td><td><code>k3</code>：最高 1M<br><code>k3-256k</code>：256K<br><code>kimi-for-coding</code>：256K<br><code>kimi-for-coding-highspeed</code>：256K</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">模型上新推荐</p><p><code>k3-256k</code>全新上线，256k上下文内效果相同, <code>k3</code>（1M）消耗约为 <code>k3-256k</code> 两倍，适合日常问答、代码补全、常规功能开发、单文件或少量文件修场景，不支持视频输入。如从 <code>k3</code>（1M 版本）切换至 <code>k3-256k</code>，建议先压缩上下文再切换。</p></div><h2 id="接入原理" tabindex="-1">接入原理 <a class="header-anchor" href="#接入原理" aria-label="Permalink to “接入原理”">​</a></h2><p>Codex CLI 使用 OpenAI Responses API，而 Kimi For Coding 提供 OpenAI 兼容的 Chat Completions API。两者协议不兼容，因此需要本地路由层做请求与流式响应的双向转换：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Codex CLI → CC Switch（本地路由） → Kimi For Coding API</span></span></code></pre></div><p>下文以 <strong>CC Switch</strong> 为例。使用 Kimi For Coding Provider 期间，请保持 CC Switch 和 Codex 路由处于运行状态。</p><h2 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to “准备工作”">​</a></h2><p>开始前，请完成以下准备：</p><ol><li>按照 <a href="https://developers.openai.com/codex/cli" target="_blank" rel="noreferrer">Codex 官方文档</a> 安装 Codex CLI，并至少启动一次。</li><li>在 <a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">Kimi Code 控制台</a> 创建并保存 API Key。</li><li>按照 <a href="https://ccswitch.io/zh/docs?section=getting-started&amp;item=installation" target="_blank" rel="noreferrer">CC Switch 官方指引</a> 下载并安装适合当前操作系统的版本。</li></ol><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>CC Switch 是第三方开源工具，不由 Kimi 维护。使用前请根据所在组织的安全与合规要求评估；API Key 以及 Codex 的请求和响应将由其本地路由处理。</p></div><p>完成安装后，打开 CC Switch，再按下面步骤操作。</p><h2 id="第一步-开启-codex-路由" tabindex="-1">第一步：开启 Codex 路由 <a class="header-anchor" href="#第一步-开启-codex-路由" aria-label="Permalink to “第一步：开启 Codex 路由”">​</a></h2><p>在 CC Switch 中进入 <strong>设置 &gt; 路由</strong>：</p><ol><li>开启 <strong>路由总开关</strong>，启动本地路由服务。</li><li>在 <strong>路由启用</strong> 区域开启 <strong>Codex</strong>。</li></ol><p><img src="/code/docs/images/zh/third-party-tools/codex/enable-codex-routing.webp" alt="开启路由总开关和 Codex 路由"></p><h2 id="第二步-添加-kimi-for-coding-provider" tabindex="-1">第二步：添加 Kimi For Coding Provider <a class="header-anchor" href="#第二步-添加-kimi-for-coding-provider" aria-label="Permalink to “第二步：添加 Kimi For Coding Provider”">​</a></h2><ol><li>返回 CC Switch 主界面，选择顶部的 <strong>Codex</strong> Tab。</li><li>点击右上角的 <strong>+</strong>，添加供应商。</li></ol><p><img src="/code/docs/images/zh/third-party-tools/codex/open-codex-provider-list.webp" alt="CC Switch 主界面，点击右上角 + 添加供应商"></p><ol start="3"><li>确认当前位于 <strong>Codex 供应商</strong> 页面，在预设供应商列表中选择 <strong>Kimi For Coding</strong>。</li></ol><p><img src="/code/docs/images/zh/third-party-tools/codex/select-kimi-provider.png" alt="预设供应商列表，选择 Kimi For Coding"></p><ol start="4"><li>填写以下配置：</li></ol><table tabindex="0"><thead><tr><th>配置项</th><th>值</th></tr></thead><tbody><tr><td>API 请求地址（Base URL）</td><td><code>https://api.kimi.com/coding/v1</code></td></tr><tr><td>API Key</td><td>在 Kimi Code 控制台创建的 API Key</td></tr></tbody></table><p><img src="/code/docs/images/zh/third-party-tools/codex/configure-kimi-provider.png" alt="填写 API Key 和 API 请求地址"></p><ol start="5"><li>向下滚动到 <strong>模型映射</strong>，点击 <strong>获取模型列表</strong>，CC Switch 会拉取 Kimi For Coding 当前支持的模型。然后按下表逐一填写 <strong>菜单显示名</strong> 和 <strong>上下文窗口</strong>：</li></ol><div class="tip custom-block"><p class="custom-block-title">模型上新推荐</p><p><code>k3-256k</code>全新上线，256k上下文内效果相同, <code>k3</code>（1M）消耗约为 <code>k3-256k</code> 两倍，适合日常问答、代码补全、常规功能开发、单文件或少量文件修场景，不支持视频输入。如从 <code>k3</code>（1M 版本）切换至 <code>k3-256k</code>，建议先压缩上下文再切换。</p></div><table tabindex="0"><thead><tr><th>菜单显示名（建议）</th><th>实际请求模型</th><th>上下文窗口</th></tr></thead><tbody><tr><td><code>K3</code></td><td><code>k3</code></td><td><code>1048576</code>（无 1M 权限时填 <code>262144</code>）</td></tr><tr><td><code>K3-256K</code></td><td><code>k3-256k</code></td><td><code>262144</code></td></tr><tr><td><code>K2.7 Code</code></td><td><code>kimi-for-coding</code></td><td><code>262144</code></td></tr><tr><td><code>K2.7 Code HighSpeed</code></td><td><code>kimi-for-coding-highspeed</code></td><td><code>262144</code></td></tr></tbody></table><p>同时确认以下高级配置：</p><table tabindex="0"><thead><tr><th>配置项</th><th>值</th></tr></thead><tbody><tr><td>上游格式</td><td><code>Chat Completions（需开启路由）</code></td></tr><tr><td>提示词缓存路由</td><td><code>自动（推荐）</code></td></tr><tr><td>支持思考模式</td><td>开启（<strong>必须开启</strong>，关闭后 K3 和 K2.7 Code 都会被路由到 K2.6）</td></tr><tr><td>支持思考等级</td><td>开启</td></tr></tbody></table><ol start="6"><li>确认无误后，点击右下角的 <strong>添加</strong>。</li></ol><p><img src="/code/docs/images/zh/third-party-tools/codex/configure-kimi-model-mapping.png" alt="高级配置：上游格式、思考能力、模型映射"></p><h2 id="第三步-启用-kimi-for-coding-provider" tabindex="-1">第三步：启用 Kimi For Coding Provider <a class="header-anchor" href="#第三步-启用-kimi-for-coding-provider" aria-label="Permalink to “第三步：启用 Kimi For Coding Provider”">​</a></h2><p>添加完成后返回 Codex 供应商列表，在刚添加的 Kimi For Coding Provider 上点击 <strong>启用</strong>。</p><p><img src="/code/docs/images/zh/third-party-tools/codex/enable-kimi-provider.webp" alt="在 Codex 供应商列表中启用 Kimi For Coding"></p><p>启用后请确认：</p><ul><li>Kimi For Coding 是 Codex Tab 中当前启用的 Provider；</li><li>CC Switch 的本地路由正在运行；</li><li>Codex 路由开关处于开启状态。</li></ul><h2 id="第四步-启动-codex-cli" tabindex="-1">第四步：启动 Codex CLI <a class="header-anchor" href="#第四步-启动-codex-cli" aria-label="Permalink to “第四步：启动 Codex CLI”">​</a></h2><p>如果 Codex CLI 已经在运行，请先退出当前会话。然后进入需要使用的项目目录，重新启动 Codex CLI：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/your/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span></span></code></pre></div><p>重启是为了让 Codex CLI 加载 CC Switch 写入的最新 Provider 和模型配置。</p><p>启动后，先确认 Codex CLI 顶部显示的模型为 <code>k3-256k</code>（或你选用的模型），然后发送一个简单请求：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hello</span></span></code></pre></div><p>如果 Codex CLI 正常返回结果，并且底部状态栏显示 <code>k3-256k</code>（或你选用的模型），说明配置已生效。</p><p><img src="/code/docs/images/zh/third-party-tools/codex/verify-codex-cli.png" alt="在 Codex CLI 中验证 k3 已生效"></p><p>也可以查看 CC Switch 的路由请求数或请求日志，确认其中出现了新的 Codex 请求。</p><h2 id="切换思考程度-effort" tabindex="-1">切换思考程度（effort） <a class="header-anchor" href="#切换思考程度-effort" aria-label="Permalink to “切换思考程度（effort）”">​</a></h2><p>K3 支持 <code>low</code> / <code>high</code> / <code>max</code> 三档思考程度。在 Codex CLI 会话中，输入 <code>/model</code> 重新选中当前模型，然后在 <strong>Select Reasoning Level</strong> 菜单中选择档位：</p><p><img src="/code/docs/images/zh/third-party-tools/codex/select-reasoning-level.png" alt="Codex CLI 中选择 Reasoning Level"></p><p>Codex 展示的档位与 K3 实际 effort 的映射关系如下（完整映射规则见 <a href="/code/docs/kimi-code/models.html#switch-model">模型配置</a>）：</p><table tabindex="0"><thead><tr><th>Codex Reasoning Level</th><th>K3 实际 effort</th></tr></thead><tbody><tr><td>Low</td><td><code>low</code></td></tr><tr><td>Medium (default)</td><td><code>high</code>（推荐）</td></tr><tr><td>High</td><td><code>high</code>（推荐）</td></tr><tr><td>Extra high</td><td><code>max</code></td></tr></tbody></table><p>切换档位后建议新建会话，避免旧上下文缓存失效带来的额外消耗。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="codex-启动后仍使用原模型" tabindex="-1">Codex 启动后仍使用原模型 <a class="header-anchor" href="#codex-启动后仍使用原模型" aria-label="Permalink to “Codex 启动后仍使用原模型”">​</a></h3><p>CC Switch 写入的配置未生效，或 Codex CLI 未重启。退出当前 Codex 会话后重新启动，并确认 CC Switch 的本地路由处于运行状态。</p><h3 id="无法连接本地路由地址" tabindex="-1">无法连接本地路由地址 <a class="header-anchor" href="#无法连接本地路由地址" aria-label="Permalink to “无法连接本地路由地址”">​</a></h3><p>CC Switch 未启动，或 Codex 路由开关未打开。启动 CC Switch，检查 <strong>设置 &gt; 路由</strong> 中的总开关和 Codex 开关是否都已开启。</p><h3 id="返回-401-或鉴权错误" tabindex="-1">返回 401 或鉴权错误 <a class="header-anchor" href="#返回-401-或鉴权错误" aria-label="Permalink to “返回 401 或鉴权错误”">​</a></h3><p>API Key 未配置、过期，或当前套餐权限不足。在 <a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">Kimi Code 控制台</a> 重新生成 API Key，并确认套餐支持所选模型（见上方<a href="#会员权限">会员权限</a>表）。</p><h3 id="请求格式或流式响应报错" tabindex="-1">请求格式或流式响应报错 <a class="header-anchor" href="#请求格式或流式响应报错" aria-label="Permalink to “请求格式或流式响应报错”">​</a></h3><p>上游格式未设为 Chat Completions，或路由未开启。在 Provider 高级配置中确认 <strong>上游格式</strong> 为 <code>Chat Completions（需开启路由）</code>。</p><h3 id="模型参数报错" tabindex="-1">模型参数报错 <a class="header-anchor" href="#模型参数报错" aria-label="Permalink to “模型参数报错”">​</a></h3><p>Kimi 模型对部分采样参数有固定要求。不要在 CC Switch 中强行覆盖 <code>temperature</code>、<code>top_p</code>、<code>n</code> 等字段。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code/models.html">模型配置</a> — 查看模型的能力对比和完整 effort 映射表</li><li><a href="/code/docs/kimi-code/membership.html">会员权益</a> — 确认可用模型与档位要求</li></ul>`,69)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};